require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../core/SmsTemplateService.php';
Auth::requirePermission('sms_template_manage');$pageTitle='قالب‌های پیامک';$editId=max(0,(int)($_GET['edit']??0));$editing=$editId?Database::fetch('SELECT * FROM sms_templates WHERE id=?',[$editId]):null;
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('درخواست نامعتبر است.','danger');redirect('/admin/sms-templates.php');}try{$action=(string)($_POST['action']??'save');$id=max(0,(int)($_POST['id']??0));if($action==='toggle'){Database::execute('UPDATE sms_templates SET is_active=IF(is_active=1,0,1),updated_at=NOW() WHERE id=?',[$id]);flash('وضعیت قالب تغییر کرد.');}else{$code=trim((string)($_POST['code']??''));$title=trim((string)($_POST['title']??''));$body=trim((string)($_POST['body']??''));if(!preg_match('/^[a-z0-9_.-]{2,100}$/',$code)||$title===''||$body==='')throw new InvalidArgumentException('کد لاتین معتبر، عنوان و متن قالب الزامی است.');$duplicate=Database::fetch('SELECT id FROM sms_templates WHERE code=? AND id<>? LIMIT 1',[$code,$id]);if($duplicate)throw new InvalidArgumentException('کد قالب قبلاً ثبت شده است.');$params=[$code,$title,trim((string)($_POST['module_key']??''))?:null,trim((string)($_POST['event_key']??''))?:null,$body,!empty($_POST['is_active'])?1:0];if($id){Database::execute('UPDATE sms_templates SET code=?,title=?,module_key=?,event_key=?,body=?,is_active=?,updated_at=NOW() WHERE id=?',[...$params,$id]);}else Database::execute('INSERT INTO sms_templates(code,title,module_key,event_key,body,is_active,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,NOW(),NOW())',[...$params,(int)Auth::user()['id']]);flash('قالب پیامک ذخیره شد.');}Auth::log((int)Auth::user()['id'],'sms_template_'.$action,'sms_templates',$id?:null);}catch(InvalidArgumentException $e){flash($e->getMessage(),'danger');}catch(Throwable $e){error_log('SMS template: '.get_class($e));flash('ذخیره قالب انجام نشد.','danger');}redirect('/admin/sms-templates.php');}
$rows=Database::fetchAll('SELECT * FROM sms_templates ORDER BY is_active DESC,title');require __DIR__.'/../views/partials/admin-header.php';?>
<form class="card admin-form" method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=e((string)($editing['id']??0))?>"><h2><?=$editing?'ویرایش قالب':'قالب جدید'?></h2><div class="grid grid-2"><label class="form-field"><span>کد</span><input dir="ltr" name="code" required value="<?=e($editing['code']??'')?>"></label><label class="form-field"><span>عنوان</span><input name="title" required value="<?=e($editing['title']??'')?>"></label><label class="form-field"><span>ماژول</span><input dir="ltr" name="module_key" value="<?=e($editing['module_key']??'')?>"></label><label class="form-field"><span>رویداد</span><input dir="ltr" name="event_key" value="<?=e($editing['event_key']??'')?>"></label></div><label class="form-field"><span>متن</span><textarea name="body" rows="5" required><?=e($editing['body']??'')?></textarea></label><label class="checkbox-item"><input type="checkbox" name="is_active" value="1" <?=!$editing||!empty($editing['is_active'])?'checked':''?>> فعال</label><p class="muted">جای‌گذارها: <?='{'.implode('}، {',SmsTemplateService::PLACEHOLDERS).'}'?></p><button class="btn btn-primary">ذخیره قالب</button></form>
<section class="card"><h2>قالب‌ها</h2><div class="table-wrap"><table><thead><tr><th>کد</th><th>عنوان</th><th>ماژول/رویداد</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td dir="ltr"><?=e($row['code'])?></td><td><?=e($row['title'])?></td><td><?=e(($row['module_key']?:'-').' / '.($row['event_key']?:'-'))?></td><td><?=$row['is_active']?'فعال':'غیرفعال'?></td><td><a class="btn btn-small" href="?edit=<?=$row['id']?>">ویرایش</a><form method="post" style="display:inline"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=$row['id']?>"><button class="btn btn-small" name="action" value="toggle">تغییر وضعیت</button></form></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="5">هنوز قالب پیامکی تعریف نشده است.</td></tr><?php endif?></tbody></table></div></section>
